        desc = {
            ALCAZ = "Ilha Alcaz: uma prisão onde Irmandade Défias mantinha nobres por resgate, hoje sitiada pelos nagas.",
            BARROW = "Uma vasta rede de túmulos dos elfos noturnos que guarda os prisioneiros mais perigosos do mundo, e a corrupção se espalha.",
            BFD = "Praia de Zoram: um templo inundado dos elfos noturnos, agora tomado por nagas, sátiros e cultistas a serviço de Aku'mai.",
            BLACKMAW = "Azshara, norte: uma grande cidade furbolg que luta contra a própria corrupção. Seus túneis descem até Profundezas Tumulares.",
            BRD = "Montanha Rocha Negra: sob a montanha fica a capital incandescente de Anões Ferro Negro, governada por Imperador Dagran Thaurissan.",
            DAL = "Com a barreira de Kirin Tor falhando, a cidade violeta é tomada por encantamentos descontrolados, constructos arcanos e energia demoníaca vazando.",
            DM = "Sob as minas abandonadas de Arroio da Lua, Irmandade Défias constrói um colosso para atacar Ventobravo. Seu líder: Edwin VanCleef.",
            DME = "Os jardins orientais tomados pela vegetação de uma antiga cidade élfica, onde Azzin, o Selvamorfo corrompe as árvores ancestrais.",
            DMN = "Os ogros tomaram os pátios do norte de uma antiga cidade élfica. Seu líder: Rei Gordok. Derrote-o e reivindique o tributo.",
            DMW = "Na ala oeste, os Altaneiros drenam o demônio Immol'thar, sob as ordens de Príncipe Tortheldrin.",
            DROWNED = "Selva do Espinhaço: ruínas trolls submersas emergiram do mar na costa, e trolls, nagas e piratas disputam o que há dentro delas.",
            EXC = "Uma escavação da Liga dos Exploradores abriu antigos salões titânicos: névoa estranha, clarões de luz e constructos ainda de guarda.",
            GNOMER = "A capital irradiada dos gnomos, perdida para os troggs e para a traição de Mecangenheiro Termaplugue.",
            HOT = "Altaforja: sob a cidade antiga, invasores de Anões Ferro Negro entraram nas tumbas reais dos antigos thanes, e os mortos inquietos despertaram.",
            HYJAL = "Monte Hyjal: algo está drenando o poder das terras ao redor, onde fantasmas de uma guerra antiga ainda vagam.",
            KROLDOK = "Uma enorme fortaleza ogra cujos saqueadores fazem prisioneiros, e cujos cânticos noturnos sugerem ligação com cultistas.",
            LBRS = "Os salões inferiores de uma fortaleza de orcs e ogros, sob as ordens de Lorde Supremo Wyrmthalak. Dez jogadores no Forever.",
            MARA = "Desolação: uma caverna sagrada dos centauros, corrompida pela elemental da terra Princesa Theradras.",
            ONY = "Onyxia, filha do grande dragão negro, aguarda em seu covil (Pântano Vadeoso). Liberada com o primeiro tier de raide do Forever.",
            RFC = "Orgrimmar: nas cavernas vulcânicas sob a cidade, troggs e cultistas (Lâmina Ardente) conspiram nas sombras, e Horda está ameaçada.",
            RFD = "Os antigos cemitérios dos javaleses caíram nas mãos do Flagelo, liderado pelo lich Amnennar, o Frigífero.",
            RFK = "Sertões, sul: um labirinto espinhoso, lar dos javaleses e de sua sacerdotisa Charlga Talhaflanco.",
            ROL = "O Flagelo ainda domina a capital em ruínas acima de Cidade Baixa, onde um necromante acumula poder entre as cinzas.",
            SCHOLO = "Castro das Flechas: nas criptas sob o castelo, cultistas fundaram uma escola de necromancia, comandada por Umbromestre Gandling.",
            SFK = "Floresta de Pinhaprata: Arquimago Arugal e seus worgens dominam a fortaleza, e sua maldição se espalha cada vez mais.",
            SHAPER = "Cratera Un'Goro: nas colinas há uma instalação titânica intacta, vibrando com cristais de poder e uma energia que ninguém explica.",
            SMARM = "O arsenal da ordem (Cruzada Escarlate) é guardado por seu campeão, Herodes.",
            SMCATH = "No coração do monastério, Comandante Escarlate Mograine e Alta-inquisidora Cristalba lideram os fanáticos.",
            SMGY = "Cruzados inquietos assombram o cemitério do monastério, onde Mago Sangrento Thalnos ainda ronda.",
            SMLIB = "Mestre de Matilha Lobato e Arcanista Doan guardam os tomos proibidos da ordem (Cruzada Escarlate).",
            ST = "O templo submerso onde os sacerdotes trolls tentam invocar o deus do sangue. Sua encarnação: Avatar de Hakkar.",
            STOCKS = "A prisão de Ventobravo caiu no caos: detentos (Irmandade Défias) tomaram os blocos de celas, liderados por Basílio Taborda.",
            STRATLIVE = "Stratholme: Cruzada Escarlate defende contra o Flagelo as ruas em chamas atrás do portão principal.",
            STRATUD = "Stratholme: Barão Rivendare governa a metade da cidade dominada pelo Flagelo, atrás da entrada de serviço.",
