            ["Type /lf collect stop to cancel. Please stay logged in."] = "Digite /lf collect stop para cancelar. Por favor, continue conectado.",
            ["Type /reload, then send the file WTF\\Account\\<account>\\SavedVariables\\Lootified.lua."] = "Digite /reload e depois envie o arquivo WTF\\Account\\<conta>\\SavedVariables\\Lootified.lua.",
            ["Type a name, a slot or a place: the list follows as you type. The switch beside it and Sort change what shows and in which order."] = "Digite um nome, um espaço ou um lugar: a lista acompanha enquanto você digita. A chave ao lado e Ordem mudam o que aparece e em que ordem.",
